// Captures what the Player's own write routes put on the wire and leave in the database, by running the real Player Route
// Handlers (apps/player/src/app/api/me/**, account/contact-change) and the real @rotra/db services (Prisma) against a
// throwaway local Postgres. The harness is capture-writes-base.mjs; the Go side is apps/api/internal/writetest. Groups:
//   profile         PATCH /api/me/profile, POST /api/me/profile-banner, POST /api/me/stats-visibility
//   privacy         POST /api/me/{profile-visibility,directory-visibility,phone-privacy}
//   notifications   PATCH /api/me/notifications, PATCH /api/me/notifications/{notificationId}
//   clubs           POST /api/me/clubs, DELETE /api/me/clubs/{clubId}
//   contact         POST /api/account/contact-change
//   register        POST /api/register/{clubId}   (a visitor: no session)
//   claim           POST /api/claim/{token}       (a visitor, a club record's link: RTR ID by the entry email, claimSharedEntry)
//   googleflow      the Google routes after the trip to Google, with the held Google sign-in and the result stubbed (see the mock below)
//   google          the seven Google sign-in routes (D-2026-11-16-01): only what is decided before the provider is needed; no Google here
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55461:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55461/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-writes-player.test.mjs [-t profile]
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it. The cases and the
// seed (player.seed.sql) are generated by gen-writes-player-cases.py. Output: apps/api/internal/playerwrites/testdata/<group>.golden.json.
//
// What is replaced, and only this:
//   AUTH_PROVIDER      'rotra', the provider the seed's player accounts carry (the Go sign-in), with verifySubject:
//   verifySubject      answers the step's subject (a step with none is signed out), so loadAccountContext and every service run for
//                      real. The seed's player accounts are linked with the provider 'rotra', which is what Go has; the subject is
//                      what the session would have said. An unknown subject has no account (wrong_account here; Go has no sign-in
//                      identity for it and answers 401: the cases say so with goExpects).
//   loginHasPassword   the sign-in provider is asked only when an account has a Google email, for MyAccount.hasPassword. There is no
//                      Supabase here and Go has none: a login is an identity (auth_identities), and it has a password when its hash
//                      is not empty. This mock does what Go does.
//   supabaseProviderAdmin / createSupabaseServer   (register group only) an in-memory provider: see the comment above vi.mock below.
//                      The Go side has no Supabase either; it makes the identity and the session itself, which the capture cannot see,
//                      so the register cases ignore the Set-Cookie header and no auth table is in the snapshot.
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, test, vi } from 'vitest'
import { captureWrites, openCaptureDb, root } from './capture-writes-base.mjs'


vi.mock('../../../../packages/db/src/auth/supabase-provider-admin.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  supabaseProviderAdmin: () => ({
    createLogin: async ({ operationRef, email, initialPassword }) => {
      const { ProviderError } = await import('../../../../packages/db/src/auth/provider-admin.ts')
      if (!email || !initialPassword || initialPassword.length < 6) throw new ProviderError('provider_rejected')
      const existing = globalThis.__logins.get(email)
      if (existing) {
        if (existing.ref !== operationRef) throw new ProviderError('provider_conflict')
        return { subject: existing.subject }
      }
      const subject = crypto.randomUUID()
      globalThis.__logins.set(email, { subject, ref: operationRef, password: initialPassword })
      return { subject }
    },
  }),
  loginHasPassword: async (subject) => {
    const { rows } = await globalThis.__captureDb.query(
      `SELECT (password_hash <> '') AS present FROM auth_identities WHERE id = $1`,
      [subject],
    )
    return rows[0]?.present ?? false
  },
  // Whether any ROTRA account is mapped to this provider login: here the account's sign-in subject, whatever its provider.
  loginHasRotraAccount: async (subject) => {
    const { rows } = await globalThis.__captureDb.query(
      `SELECT EXISTS (SELECT 1 FROM player_accounts WHERE auth_subject = $1) AS present`,
      [subject],
    )
    return rows[0].present
  },
}))

// The held Google sign-in and the result of a trip to Google (group googleflow). In the TypeScript the held sign-in is a provider
// session and the result a cookie; there is no Google and no Supabase here, so a case declares both in one cookie, `capture-google`
// (base64url JSON: held {subject, email, name, googleOnly}, result {key, intent, outcome, email, name}), and only the reads of what the
// browser holds are answered from it. Every decision, service and database write after them runs for real. The signed-in player is
// the step's subject, as everywhere in this harness.
const googleStub = (jar) => {
  const value = jar.cookies.getAll().find((cookie) => cookie.name === 'capture-google')?.value
  return value ? JSON.parse(Buffer.from(value, 'base64url').toString('utf8')) : {}
}
vi.mock('../../../../packages/db/src/auth/google-oauth.ts', async (importOriginal) => {
  const actual = await importOriginal()
  return {
  ...actual,
  currentPlayerSession: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { subject, oauth: true, sessionId: null } : null
  },
  // The result goes through the real reader (its key, intent and outcome checks), from the cookie the TypeScript itself would have set.
  readGoogleResult: (jar) => {
    const result = googleStub(jar).result
    if (!result) return null
    const value = Buffer.from(JSON.stringify(result), 'utf8').toString('base64url')
    return actual.readGoogleResult({ cookies: { getAll: () => [{ name: 'rotra-player-google-result', value }] } })
  },
  readPendingGoogle: async (jar) => {
    const held = googleStub(jar).held
    if (!held) return null
    // The provider's own user for this Google login (auth.users in Supabase): the account made for it points at it.
    await globalThis.__captureDb.query(
      `INSERT INTO auth_identities (id, audience, login_key, password_hash, password_scheme, password_changed_at, created_at, updated_at, revision)
       VALUES ($1, 'player', $2, '', 'argon2id', now(), now(), now(), 1) ON CONFLICT DO NOTHING`,
      [held.subject, held.email],
    )
    return {
      subject: held.subject,
      google: { email: held.email, name: held.name },
      googleOnly: held.googleOnly,
      tokens: { accessToken: 'held-access', refreshToken: 'held-refresh' },
    }
  },
  promotePendingGoogle: async () => true,
  dropPendingGoogle: async () => undefined,
  dropGoogleSession: async () => undefined,
  signOutPlayerHere: async () => undefined,
  }
})

// The registration signs the new player up and in through Supabase. There is no Supabase here, and only its calls are replaced
// (an in-memory provider, reset before every case): createLogin keeps one login per email under the operation that made it, as
// supabase-provider-admin.ts does (the same operation gets the same login, another one is provider_conflict, a password under 6
// characters is refused), and signInWithPassword checks the password the login was made with. The provider keeps its logins in
// auth.users; the capture database has no auth schema, so the preflight of stageRegistration reads a view of auth_identities
// (the Go sign-in logins, which is what reserves an email now), made in beforeAll below.
globalThis.__logins = new Map()
vi.mock('../../../../packages/db/src/auth/supabase.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  AUTH_PROVIDER: 'rotra',
  createSupabaseServer: () => ({
    auth: {
      signInWithPassword: async ({ email, password }) => {
        const login = globalThis.__logins.get(email)
        if (!login || login.password !== password)
          return { data: { user: null }, error: { status: 400, message: 'Invalid login credentials' } }
        return { data: { user: { id: login.subject } }, error: null }
      },
      signOut: async () => ({ error: null }),
    },
  }),
  verifySubject: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { provider: 'rotra', subject } : null
  },
}))

const here = dirname(fileURLToPath(import.meta.url))
const testdata = resolve(here, '../../internal/playerwrites/testdata')
const apiDir = resolve(root, 'apps/player/src/app/api')

let capture
beforeAll(async () => {
  capture = await openCaptureDb()
  globalThis.__captureDb = capture.db
  await capture.db.query(`CREATE SCHEMA IF NOT EXISTS auth; CREATE VIEW auth.users AS SELECT id, login_key AS email FROM auth_identities`)
})
afterAll(async () => {
  await capture?.close()
})

for (const name of ['profile', 'privacy', 'notifications', 'clubs', 'leavetransfers', 'contact', 'register', 'claim', 'google', 'googleflow']) {
  test(name, async () => {
    await captureWrites({ db: capture.db, testdata, name, apiDir, beforeCase: () => globalThis.__logins.clear() })
  })
}
